(()=>{const node=document.getElementById('error');let ready=false;window.mobileMapHealth={stage:'BOOT',reason:null};const fail=reason=>{window.mobileMapHealth={stage:'ERROR',reason};node.textContent=reason==='GRAPHICS'?'Map graphics unavailable. Native controls remain available.':'Map could not load. Check internet access; native controls remain available.';node.hidden=false;};window.mobileMapReady=()=>{ready=true;window.mobileMapHealth={stage:'READY',reason:null};node.hidden=true;};window.mobileMapFail=fail;window.addEventListener('error',()=>fail('STARTUP'),true);window.addEventListener('unhandledrejection',()=>fail('STARTUP'));setTimeout(()=>{if(!ready)fail('STARTUP');},15000);})();
